package com.primehr.learningdevelopment.evaluation.api;
import com.primehr.learningdevelopment.evaluation.api.LdEvaluationDtos.CompletionFeedPage;import com.primehr.learningdevelopment.evaluation.application.LdEvaluationService;import com.primehr.security.*;import org.springframework.http.*;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.time.Instant;
@RestController public class LdCompletionFeedController {private final LdEvaluationService service;private final LdEvaluationPermissionGuard permission;private final AgencyScopeResolver agencies;public LdCompletionFeedController(LdEvaluationService service,LdEvaluationPermissionGuard permission,AgencyScopeResolver agencies){this.service=service;this.permission=permission;this.agencies=agencies;}@GetMapping("/api/primehr/integration/v1/learning-completions")public CompletionFeedPage feed(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String token,@RequestHeader(value="X-Correlation-Id",required=false)String correlation,@RequestParam Instant changedAfter,@RequestParam Instant changedThrough,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="100")int size){permission.require(LdEvaluationPermissionGuard.COMPLETION_FEED,PrimeHrAction.ACCESS,token);return service.completionFeed(agencies.resolveAgencyId(a),changedAfter,changedThrough,page,size,a.getName(),correlation);}}
